      slug = '{"uz":"yangi-yil-sovga-qutisi-qasr-karobka-qorbobo-qasri","ru":"novogodnyaya-podarochnaya-korobka-teremok-dvorets-deda-moroza","en":"new-year-palace-candy-box-santa-palace"}',
