      slug = '{"uz":"yangi-yil-sovga-qutisi-ip-tutqichli-karobka-qorbobo-va-qorbolalar","ru":"novogodnyaya-podarochnaya-korobka-s-ruchkoy-shnurkom-ded-moroz-i-snegoviki","en":"new-year-rope-handle-gift-box-santa-snowmanlar"}',
