      slug = '{"uz":"yangi-yil-sovga-qutisi-gumbaz-karobka-qorbobo-va-ayiqcha-qorxodda","ru":"novogodnyaya-podarochnaya-korobka-fonarik-ded-moroz-i-medvezhonok-na-snegokhode","en":"yangi-yil-sovga-qutisi-gumbaz-karobka-santa-bear-on-snowmobile"}',
      price = 9500,
      category = 'yangi-yil-2027',
