INSERT INTO public.blog_posts (id, title, slug, image, content, date, seo)
VALUES (
  28,
  '{"uz":"Bir martalik (odnorazoviy) idishlar va konteynerlar O''rikzor optom narxlarida: Kafe va Dostavka xizmatlari uchun","ru":"Одноразовая посуда и контейнеры по оптовым ценам Урикзор: Для кафе, фастфуда и служб доставки","en":"Disposable Tableware and Food Containers at Urikzor Wholesale Prices: For Cafes, Fast Food, and Delivery Services"}',
  '{"uz":"bir-martalik-odnorazoviy-idishlar-optom-orikzor-narxlari","ru":"odnorazovaya-posuda-i-konteynery-optom-urikzor","en":"disposable-tableware-containers-wholesale-urikzor"}',
  'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?q=80&w=1200&auto=format&fit=crop',
  '{"uz":"Restoran, kafe, kofexona va tezkor ovqat yetkazib berish (fast-food delivery) xizmatlarining daromadliligi to''g''ridan-to''g''ri bir martalik idishlarning tannarxiga va sifatiga bog''liq. Taom yetib borguncha sovuq qolmasligi, souslar oqib ketmasligi va qog''oz stakan qo''lni kuydirmasligi mijozning sizga ikkinchi bor buyurtma berishini ta''minlaydi.\n\n[LUXECORE (luxe-core.uz)](https://luxe-core.uz/uz) O''rikzor ulgurji bozoridagi eng yirik ombordan umumiy ovqatlanish korxonalari (HoReCa) uchun sifatli bir martalik idish-tovoqlar va qadoqlarni ulgurji narxda taklif etadi.\n\n### 1. Kafe va Dostavka Uchun Zaruriy Asosiy Mahsulotlar\n\n- **Germetik Bir Martalik Sous Idishlari:** [Issiq taomlar uchun qopqoqli qora konteyner (750 ml)](/uz/product/28) qalin plastikdan tayyorlangan, qopqog''i mahkam yopiladi, sous, ketchup va mayonezlarning to''kilib ketishidan 100% kafolat beradi.\n- **Ikki Qavatli Kraft Kofe Stakanlari:** [Ikki qavatli (Double Wall) kofe stakani (250 ml + qopqoq)](/uz/product/26) — qo''lni kuydirmaydigan ikki qavatli (Double Wall) devorga ega, qopqog''i zich yopiladi, taom yetkazish va take-away uchun ideal.\n- **Issiq Taomlar Uchun Qora Polipropilen Konteynerlar:** Mikroto''lqinli pechda qizdirishga chidamli, deformatsiyalanmaydigan 500, 750 va 1000 ml sig''imdagi lanch-bokslar.\n- **Fast-Food Qutilari va Qog''oz Kraft Paketlar:** Burger, lavash, fri kartoshkalari uchun yog'' o''tkazmaydigan ekologik qutilar.\n\n### 2. 3 Pog''onali Ulgurji Chegirma Tizimi\n\nDoimiy iste''mol qilinadigan bir martalik idishlarda har bir so''m katta mablag''ga aylanadi:\n- **100 – 499 dona:** Kichik kafelar uchun hamyonbop bazaviy ulgurji narx;\n- **500 – 999 dona:** Avtomatik **-5% chegirma**;\n- **1 000+ dona:** Avtomatik **-10% VIP chegirma**.\n\nYirik tarmoq kafelar har oy qadoqlashga sarflanadigan byudjetidan millionlab so''mni tejab qolmoqda.\n\n### 3. Pachkalab Qulay Xarid (1x, 2x, 5x, 10x)\n\nOshxona xodimlari soni adashmasligi uchun barcha mahsulotlar qat''iy standartdagi korobka va pachkalarda jo''natiladi:\n- **1x pachka** (masalan, 220 dona sous idishi yoki 50 dona stakan);\n- **2x pachka** (440 dona);\n- **5x pachka** (1 100 dona);\n- **10x pachka** (2 200 dona va undan yuqori).\n\n### 4. 📥 Excel Prays-List va 🖨 Rasmiy Yuk Xati (Накладная)\n\n- [Katalog Sahifasida](/uz/catalog) barcha HoReCa tovarlarining to''liq ro''yxati va ulgurji narxlarini **\"📥 Prays-list (Excel)\"** tugmasi orqali yuklab olish mumkin.\n- Barcha buyurtmalarga buxgalteriya hisoboti uchun muhr va imzo qo''yilgan rasmiy **YUK XATI (НАКЛАДНАЯ) — LUXECORE (luxe-core.uz)** ilova qilinadi.\n\n### 5. 🚚 Toshkentda 2 Mln So''mdan Bepul va 2 Soatda Yetkazish\n\n- Kafe va restoranlarda idish-tovoq kutilmaganda tugab qolishini yaxshi bilamiz. Toshkent shahri ichida 2 000 000 so''mdan yuqori buyurtmalar **2 soat ichida eshigingizgacha mutlaqo bepul** yetkaziladi!\n- Har hafta tugaydigan buyurtmalarni qayta qidirib o''tirmasdan, [Buyurtmani Kuzatish va Takrorlash](/uz/tracking) sahifasida 1 ta tugma orqali darhol savatga qaytarishingiz mumkin.\n\n### 6. HoReCa Bo''limi Bilan Tanishing:\n\n- [HoReCa va Xo''jalik Ulgurji Bo''limi](/uz/category/horeca-xojalik)\n- [Issiq taomlar uchun qopqoqli konteynerlar](/uz/category/horeca-xojalik)\n- [Ikki qavatli (Double Wall) kofe stakani (250 ml + qopqoq)](/uz/product/26)\n\nHoziroq [LUXECORE Ulgurji Katalogiga](/uz/catalog) kiring va kafengiz uchun bir martalik idishlarni O''rikzor narxlarida xarid qiling!","ru":"В ресторанном бизнесе, кофейнях и службах доставки еды качество одноразовой посуды играет ключевую роль: герметичность соусников, термостойкость крафт-стаканов и прочность ланч-боксов напрямую определяют лояльность клиентов.\n\nОптовая платформа [LUXECORE (luxe-core.uz)](https://luxe-core.uz/uz) поставляет полный ассортимент одноразовой посуды и упаковки для HoReCa со склада рынка Урикзор в Ташкенте по прямым оптовым ценам.\n\n### 1. Базовые Позиции для Кафе и Доставки Еды\n\n- **Герметичные Соусники:** [Контейнер с крышкой для горячих блюд (750 мл)](/ru/product/28) из прочного полипропилена с плотной крышкой, исключающей протекание соусов, кетчупа и майонеза.\n- **Двухслойные Крафт-Стаканы:** [Двухслойный крафт-стакан Double Wall (250 мл + крышка)](/ru/product/26) с двойной стенкой (Double Wall) защищает руки от ожогов и сохраняет напиток горячим.\n- **Контейнеры для Горячих Блюд:** Черные ланч-боксы для микроволновой печи на 500, 750 и 1000 мл.\n- **Крафт-коробки для фастфуда:** Жиростойкие эко-боксы для бургеров, снеков и картофеля фри.\n\n### 2. 3 Уровня Оптовых Скидок\n\n- **100 – 499 шт:** Базовая оптовая цена для небольших кофеен;\n- **500 – 999 шт:** Автоматическая скидка **-5%**;\n- **1 000+ шт:** Автоматическая **VIP-скидка -10%**.\n\n### 3. Быстрая Фасовка Пачками (1x, 2x, 5x, 10x)\n\nУдобные кнопки выбора количества прямо в каталоге:\n- **1x пачка** — стартовый объем (например, 220 соусников или 50 стаканов);\n- **2x пачки** — 440 шт;\n- **5x пачек** — 1100 шт;\n- **10x пачек** — от 2200 шт со скидкой.\n\n### 4. 📥 Excel Прайс-Лист и 🖨 Официальная Накладная\n\n- Скачивайте полный прайс-лист в шапке [Каталога](/ru/catalog) кнопкой **\"📥 Прайс-лист (Excel)\"**.\n- К каждому заказу прилагается официальная **НАКЛАДНАЯ — LUXECORE (luxe-core.uz)** со штампом и реквизитами для бухгалтерии.\n\n### 5. 🚚 Бесплатная Доставка от 2 Млн Сум за 2 Часа\n\n- Заказы от 2 000 000 сум по Ташкенту доставляются **бесплатно в течение 2 часов**.\n- Доставка по всем регионам Узбекистана за 24 часа.\n- Повторить заказ регулярных расходников можно за 1 клик на странице [Отслеживание Заказов](/ru/tracking).\n\n### 6. Популярные Товары:\n\n- [Категория HoReCa и Хозтовары](/ru/category/horeca-xojalik)\n- [Контейнер для горячих блюд (750 мл)](/ru/product/28)\n- [Двухслойный крафт-стакан Double Wall (250 мл + крышка)](/ru/product/26)\n\nПереходите в [Каталог LUXECORE](/ru/catalog) и заказывайте одноразовую посуду для кафе по лучшим оптовым ценам!","en":"Wholesale disposable tableware and food containers at Urikzor wholesale prices in Tashkent. Sauce containers, Double Wall kraft paper cups, food boxes for restaurants and delivery services. 3-tier discounts up to 10%, official invoices, and free delivery from 2M UZS. Visit [LUXECORE Catalog](/en/catalog)!"}',
  '2026-11-02',
  '{"title":{"uz":"Bir martalik idishlar optom Toshkent — Kafe va dostavka uchun O''rikzor narxlari | LUXECORE","ru":"Одноразовая посуда оптом в Ташкенте — Цены Урикзор для кафе и доставки | LUXECORE","en":"Disposable Tableware Wholesale Tashkent — Urikzor Prices for Delivery | LUXECORE"},"description":{"uz":"Kafe, restoran va dostavka uchun bir martalik sous idishlari, kraft stakanlar, konteynerlar O''rikzor optom narxlarida. 3 pog''onali chegirma (1000+ -10%), pachkalab xarid, Excel prays-list, rasmiy Yuk xati (Накладная), 2 mln so''mdan bepul yetkazish.","ru":"Одноразовая посуда, соусники, двухслойные крафт-стаканы с крышкой и пищевые контейнеры оптом со склада Урикзор. Скидки до 10%, накладная для бухгалтерии, бесплатная доставка от 2 млн сум по Ташкенту.","en":"Wholesale disposable tableware, food containers, sauce cups, and paper coffee cups in Tashkent. Bulk discounts up to 10%, delivery over 2M UZS."},"keywords":{"uz":"bir martalik idishlar optom, odnorazoviy idishlar toshkent, sous idishi optom, kofe stakanlari ulgurji, horeca qadoqlash orikzor, kafe uchun idishlar optom, yetkazib berish idishlari","ru":"одноразовая посуда оптом ташкент, соусники оптом урикзор, крафт стаканы оптом, одноразовые контейнеры для еды, посуда для кафе оптом, упаковка для доставки еды","en":"disposable tableware wholesale tashkent, food containers wholesale, coffee paper cups bulk, horeca packaging urikzor"}}'::jsonb
)
